-- Every promote/repeat action is an explicit human decision. No automatic decisions or batches.
create table private.progression_policy(academic_year text primary key,review_threshold numeric not null check(review_threshold between 0 and 100),updated_by uuid not null references public.profiles(id),updated_at timestamptz not null default now());
create table private.progression_decisions(id uuid primary key default gen_random_uuid(),student_id text not null references public.students(student_id),source_year text not null,decision text not null check(decision in('promote','repeat')),snapshot jsonb not null,reason text not null,replaces_id uuid references private.progression_decisions(id),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),request_id uuid not null unique,payload_hash text not null);
create unique index progression_one_correction on private.progression_decisions(replaces_id)where replaces_id is not null;
create index progression_student_year on private.progression_decisions(student_id,source_year,created_at desc);
create index progression_decision_author on private.progression_decisions(created_by);
create index progression_policy_author on private.progression_policy(updated_by);
alter table private.progression_policy enable row level security;alter table private.progression_decisions enable row level security;
revoke all on private.progression_policy,private.progression_decisions from public,anon,authenticated;
create policy progression_policy_rpc_only on private.progression_policy for all to anon,authenticated using(false)with check(false);
create policy progression_decisions_rpc_only on private.progression_decisions for all to anon,authenticated using(false)with check(false);
create function private.progression_context(target_student text)returns jsonb language plpgsql security definer set search_path=''as $$declare st jsonb;begin
 if not private.has_school_role(array['headmaster','dean'])then raise exception 'Headmaster or Dean access required'using errcode='42501';end if;
 select jsonb_build_object('student_id',s.student_id,'full_name',s.full_name,'class_name',s.class_name,'status',s.status,'academic_year',c.academic_year,'grade',c.grade)into st from public.students s join public.school_classes c on c.class_name=s.class_name where s.student_id=target_student;if st is null then raise exception 'Student not found';end if;
 return jsonb_build_object('student',st,'releases',(select coalesce(jsonb_agg(to_jsonb(q)order by q.recorded_on desc,q.created_at desc),'[]')from(select a.id,a.release_name,a.academic_year,a.recorded_on,a.created_at,r.overall from public.academic_release_results r join public.academic_releases a on a.id=r.release_id where r.student_id=target_student and not exists(select 1 from public.academic_releases n where n.replaces_id=a.id)order by a.recorded_on desc,a.created_at desc limit 100)q),'decisions',(select coalesce(jsonb_agg(to_jsonb(q)order by q.created_at desc),'[]')from(select d.id,d.source_year,d.decision,d.reason,d.snapshot,d.created_at,p.display_name author_name,(select n.id from private.progression_decisions n where n.replaces_id=d.id)newer_version from private.progression_decisions d join public.profiles p on p.id=d.created_by where d.student_id=target_student order by d.created_at desc limit 100)q));
end;$$;
create function private.set_progression_threshold(academic_year text,threshold numeric)returns void language plpgsql security definer set search_path=''as $$begin
 if not private.has_school_role(array['dean'])then raise exception 'Dean of Studies access required'using errcode='42501';end if;
 if coalesce(length(btrim(academic_year)),0)not between 1 and 30 or threshold is null or threshold<0 or threshold>100 then raise exception 'Choose year and review threshold from 0 to 100';end if;
 insert into private.progression_policy(academic_year,review_threshold,updated_by)values(btrim(academic_year),threshold,auth.uid())on conflict(academic_year)do update set review_threshold=excluded.review_threshold,updated_by=auth.uid(),updated_at=now();
 insert into public.audit_events(actor_user_id,action,entity_type,entity_id,details)values(auth.uid(),'progression_review_threshold','academic_year',btrim(academic_year),jsonb_build_object('threshold',threshold,'automatic_decisions',false));
end;$$;
create function private.progression_preview(data jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
declare s public.students;c public.school_classes;dest public.school_classes;prior private.progression_decisions;last_id uuid;rid uuid;source_year text;origin jsonb;state jsonb;result jsonb;threshold numeric;academic jsonb;overall numeric;begin
 if not private.has_school_role(array['headmaster','dean'])then raise exception 'Headmaster or Dean access required'using errcode='42501';end if;
 if jsonb_typeof(data)is distinct from'object'or exists(select 1 from jsonb_object_keys(data)k where k not in('student_id','source_year','decision','destination_class','academic_release_id','reason','replaces_id','review_confirmed'))then raise exception 'Invalid manual decision';end if;
 if coalesce(length(btrim(data->>'reason')),0)not between 1 and 1000 or data->>'decision'not in('promote','repeat')or data->>'decision'is null then raise exception 'Choose Promote or Repeat and write the review conclusion';end if;
 source_year:=btrim(data->>'source_year');if coalesce(length(source_year),0)not between 1 and 30 then raise exception 'Choose the year being reviewed';end if;
 select *into s from public.students where student_id=data->>'student_id';if not found or s.status<>'Active'then raise exception 'Choose an active student';end if;
 select *into c from public.school_classes where class_name=s.class_name;
 state:=jsonb_build_object('student_id',s.student_id,'full_name',s.full_name,'class_name',s.class_name,'academic_year',c.academic_year,'grade',c.grade,'status',s.status);
 select d.id into last_id from private.progression_decisions d where d.student_id=s.student_id and d.source_year=progression_preview.source_year and not exists(select 1 from private.progression_decisions n where n.replaces_id=d.id)order by d.created_at desc limit 1;
 rid:=nullif(data->>'replaces_id','')::uuid;
 if last_id is not null and rid is distinct from last_id then raise exception 'A decision already exists for this student and year. Open it and choose Correct this decision.'using errcode='40001';end if;
 if rid is not null then select *into prior from private.progression_decisions where id=rid;if not found or prior.student_id<>s.student_id or prior.source_year<>source_year or rid is distinct from last_id then raise exception 'Choose the latest decision for this student/year';end if;origin:=prior.snapshot->'origin';else origin:=state||jsonb_build_object('academic_year',source_year);end if;
 select *into dest from public.school_classes where class_name=data->>'destination_class';if not found or dest.academic_year=source_year then raise exception 'Choose a destination class configured for the next school year';end if;
 if data->>'decision'='repeat'and dest.grade<>origin->>'grade'then raise exception 'A repeat destination must keep the original grade';end if;
 if data->>'decision'='promote'and substring(dest.grade from 2)::integer<>substring(origin->>'grade'from 2)::integer+1 then raise exception 'A promotion destination must be the next grade. Headmaster marks school leavers Graduated separately.';end if;
 rid:=nullif(data->>'academic_release_id','')::uuid;
 if rid is not null then
  select jsonb_build_object('release_id',a.id,'release_name',a.release_name,'recorded_on',a.recorded_on,'overall',r.overall,'warning_count',jsonb_array_length(a.warnings))into academic from public.academic_releases a join public.academic_release_results r on r.release_id=a.id where a.id=rid and r.student_id=s.student_id and a.academic_year=source_year and a.class_name=origin->>'class_name'and not exists(select 1 from public.academic_releases n where n.replaces_id=a.id);
  if academic is null then raise exception 'Choose a current results version for the student, original class and review year';end if;
 elsif c.academic_year<>source_year and not exists(select 1 from private.student_enrolment_history h where h.student_id=s.student_id and((h.previous_state->>'class_name'=origin->>'class_name'and h.previous_state->>'academic_year'=source_year)or(h.next_state->>'class_name'=origin->>'class_name'and h.next_state->>'academic_year'=source_year)))and prior.id is null then raise exception 'This review year has no recorded enrolment/source for the student';end if;
 select p.review_threshold into threshold from private.progression_policy p where p.academic_year=source_year;threshold:=coalesce(threshold,50);overall:=(academic->>'overall')::numeric;
 result:=jsonb_build_object('student',state,'origin',origin,'source_year',source_year,'decision',data->>'decision','destination',jsonb_build_object('class_name',dest.class_name,'academic_year',dest.academic_year,'grade',dest.grade),'academic',academic,'review_threshold',threshold,'needs_mark_review',overall is null or overall<threshold,'warning',case when overall is null then'No overall percentage is recorded. Review the school records before making this manual decision.'when overall<threshold then'The recorded percentage is below the review threshold. The Headmaster or Dean must make and explain the decision.'else'This is still a manual decision; no student is promoted automatically.'end,'replaces_id',nullif(data->>'replaces_id','')::uuid);
 return jsonb_build_object('snapshot',result,'preview_token',encode(sha256(convert_to(data::text||result::text,'UTF8')),'hex'));
end;$$;
create function private.apply_progression_decision(data jsonb,preview_token text,request_id uuid)returns uuid language plpgsql security definer set search_path=''as $$
declare prior private.progression_decisions;p jsonb;rid uuid:=gen_random_uuid();fingerprint text:=encode(sha256(convert_to(data::text,'UTF8')),'hex');begin
 if not private.has_school_role(array['headmaster','dean'])then raise exception 'Headmaster or Dean access required'using errcode='42501';end if;
 if request_id is null or data->'review_confirmed'is distinct from'true'::jsonb then raise exception 'Explicit human review confirmation required';end if;
 perform pg_advisory_xact_lock(hashtextextended('progression-request:'||request_id::text,0));
 select *into prior from private.progression_decisions d where d.request_id=apply_progression_decision.request_id;
 if found then if prior.created_by<>auth.uid()or prior.payload_hash<>fingerprint then raise exception 'Request differs from original manual decision';end if;return prior.id;end if;
 perform 1 from public.school_classes order by class_name for update;perform 1 from public.students where student_id=data->>'student_id'for update;
 p:=private.progression_preview(data);if p->>'preview_token'is distinct from preview_token then raise exception 'Student, results or review policy changed. Review again.'using errcode='40001';end if;
 insert into private.progression_decisions(id,student_id,source_year,decision,snapshot,reason,replaces_id,created_by,request_id,payload_hash)values(rid,data->>'student_id',data->>'source_year',data->>'decision',p->'snapshot',btrim(data->>'reason'),nullif(data->>'replaces_id','')::uuid,auth.uid(),request_id,fingerprint);
 update public.students set class_name=data->>'destination_class'where student_id=data->>'student_id';
 insert into public.audit_events(actor_user_id,action,entity_type,entity_id,details)values(auth.uid(),'manual_progression_decision','student',data->>'student_id',jsonb_build_object('decision_id',rid,'before',p->'snapshot'->'student','after',p->'snapshot'->'destination','review_year',data->>'source_year','reason',data->>'reason','automatic',false));
 insert into public.school_notifications(recipient_id,actor_id,action,target)select distinct r.user_id,auth.uid(),'manual_progression_decision',data->>'student_id'from public.user_roles r join public.profiles pr on pr.id=r.user_id where r.role='headmaster'and pr.is_active and r.user_id<>auth.uid();
 return rid;
end;$$;
create function public.progression_context(target_student text)returns jsonb language sql security invoker set search_path=''as $$select private.progression_context(target_student);$$;
create function public.set_progression_threshold(academic_year text,threshold numeric)returns void language sql security invoker set search_path=''as $$select private.set_progression_threshold(academic_year,threshold);$$;
create function public.progression_preview(data jsonb)returns jsonb language sql security invoker set search_path=''as $$select private.progression_preview(data);$$;
create function public.apply_progression_decision(data jsonb,preview_token text,request_id uuid)returns uuid language sql security invoker set search_path=''as $$select private.apply_progression_decision(data,preview_token,request_id);$$;
revoke all on function private.progression_context(text),private.set_progression_threshold(text,numeric),private.progression_preview(jsonb),private.apply_progression_decision(jsonb,text,uuid),public.progression_context(text),public.set_progression_threshold(text,numeric),public.progression_preview(jsonb),public.apply_progression_decision(jsonb,text,uuid)from public,anon;
grant execute on function private.progression_context(text),private.set_progression_threshold(text,numeric),private.progression_preview(jsonb),private.apply_progression_decision(jsonb,text,uuid),public.progression_context(text),public.set_progression_threshold(text,numeric),public.progression_preview(jsonb),public.apply_progression_decision(jsonb,text,uuid)to authenticated;
